package com.retro.launcher;
import android.app.Activity;import android.os.Bundle;import android.graphics.*;import android.graphics.drawable.*;import android.widget.*;
public class HelpActivity extends Activity {
 LinearLayout content;Typeface pixel;
 void section(String title,String body){TextView head=new TextView(this);head.setText(title);head.setTypeface(pixel);head.setTextSize(23);head.setTextColor(0xff53d8ff);head.setPadding(8,22,8,8);content.addView(head);TextView text=new TextView(this);text.setText(body);text.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));text.setTextSize(16);text.setLetterSpacing(0);text.setTextColor(0xffd7e9f6);text.setLineSpacing(5,1);text.setPadding(8,0,8,16);content.addView(text);}
 public void onCreate(Bundle state){super.onCreate(state);pixel=Typeface.createFromAsset(getAssets(),"fonts/rajdhani.ttf");ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(1);int pad=(int)(18*getResources().getDisplayMetrics().density);content.setPadding(pad,pad,pad,pad);content.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xff0c2745,0xff020b18}));scroll.addView(content);setContentView(scroll);TextView title=new TextView(this);title.setText("RETRO ORBIT / HELP");title.setTextSize(29);title.setTypeface(pixel);title.setTextColor(0xffedfaff);content.addView(title);
 section("THE WHEEL","Drag up or down over the icons to rotate the wheel. Tap any icon to open that app. Hold an icon for its options. Swipe left from home for Applications or right for Notifications.");
 section("APPLICATIONS","Tap an app to open it. Hold for favorites, icon choice, app information and wheel order. Drag up or down for continuous scrolling, or flick to coast. Touch the grid to stop it. The cyan scrollbar shows your position. Swipe left or right to move a full page, or tap the left/right ends of the page indicator. The Options button acts on the highlighted app.");
 section("NOTIFICATIONS","Tap the home preview to see the full list. Drag up or down to scroll. Alerts are grouped by app, with a count and latest preview. Tap a group to browse its individual alerts. Swipe a group right to dismiss its clearable alerts; a trash icon appears behind the sliding panel. Swipe left for group options. Short swipes return the panel to its place. The cyan scrollbar shows your position. Tap an alert to open its supplied action; hold it for options including Dismiss. Android notification access is optional and can be enabled in launcher settings. Ongoing system alerts stay in the full list but are omitted from the home summary.");
 section("ORB & ANIMATION","Tap the chrome orb to choose a photo, restore the original, preview the launch effect or turn it off. Back cancels the effect before the app opens. Photos stay on your device.");
 section("WEATHER & CLOCK","Tap the weather panel for city, units and refresh. Tap the clock/date to open system time settings. Weather needs an internet connection for fresh data and keeps a local cache. Open-Meteo attribution is retained with the reading.");
 section("FAVORITES","Use an app’s long-press menu to add or remove it from the wheel. In Reorder favorites, tap an entry and choose Move up, Move down or Remove. Changes are saved automatically.");
 section("NAVIGATION","Apps and Options are the home soft keys. Content screens provide Options and Back; tap an item to open it. Android’s own Home, Back and Recents buttons or gestures remain available; use Recents to switch between apps or dismiss a task. Set Retro Orbit as Home under Options → Default home app.");
 section("UNLOCK EFFECT","Orbit Access plays a brief visual transition after Android unlocks while Retro Orbit is visible. It does not request another fingerprint or code. Toggle Unlock effect in Options. The separate Orbit Access preview can test Android authentication. Settings, wheel-app lists, ordering and notifications support continuous drag scrolling and flick momentum.");
 section("ACCESSIBILITY & PRIVACY","Touchscreen controls work without enabling Retro Orbit’s optional accessibility service. Virtual items expose click, hold and paging actions to screen readers; a full accessibility audit is still pending. Notification contents and orb photos stay on the device. A configured city is sent to the weather provider; no GPS permission is requested.");
 Button close=new Button(this);close.setText("Back to launcher");close.setAllCaps(false);close.setTypeface(pixel);close.setTextSize(20);close.setOnClickListener(v->finish());content.addView(close,new LinearLayout.LayoutParams(-1,(int)(56*getResources().getDisplayMetrics().density)));}
}
